SELECT /*selectMasterMpRqItemReqRcptList*/ Y.BUYER ,Y.BUYER_NAME ,Y.RAV_NO ,Y.RAV_SEQ ,Y.STATUS ,Y.RFQ_USER_ID ,Y.RFQ_USER_NAME ,Y.BUYER_ITEM_NO ,DECODE(Y.ITEM_STATUS,'K','기등록','신규') AS ITEM_STATUS ,Y.DESCRIPTION ,Y.SPECIFICATION ,Y.UNIT_MEASURE ,Y.MAKER_NAME ,Y.BUYER_REMARK ,DECODE(Y.BUYER_REMARK,'',0,1) AS BUYER_REMARK_IMG ,Y.KEP_RAV_SEQ ,Y.KEP_BUYER_ITEM_NO ,Y.KEP_ITEM_STATUS ,Y.KEP_DESCRIPTION ,Y.KEP_SPECIFICATION ,Y.KEP_UNIT_MEASURE ,Y.KEP_MAKER_NAME ,Y.KEP_KEP_REMARK ,DECODE(Y.KEP_KEP_REMARK,'',0,1) AS KEP_KEP_REMARK_IMG ,DECODE(Y.FEEDBACK_FLAG,'Y','확인','미확인') AS FEEDBACK_FLAG ,Y.CONTRACT_NO ,Y.CONTRACT_SEQ ,Y.KEP_USER_ID ,Y.KEP_PHONE_NUMBER ,Y.IMAGE_KEY ,DECODE(Y.IMAGE_KEY,'',2,3) AS IMAGE_KEY_IMG FROM( SELECT ROWNUM NUM ,X.BUYER ,X.BUYER_NAME ,X.RAV_NO ,X.RAV_SEQ ,X.STATUS ,X.RFQ_USER_ID ,X.RFQ_USER_NAME ,X.BUYER_ITEM_NO ,X.ITEM_STATUS ,X.DESCRIPTION ,X.SPECIFICATION ,X.UNIT_MEASURE ,X.MAKER_NAME ,X.BUYER_REMARK ,X.KEP_RAV_SEQ ,X.KEP_BUYER_ITEM_NO ,X.KEP_ITEM_STATUS ,X.KEP_DESCRIPTION ,X.KEP_SPECIFICATION ,X.KEP_MAKER_NAME ,X.KEP_UNIT_MEASURE ,X.KEP_KEP_REMARK ,X.FEEDBACK_FLAG ,X.CONTRACT_NO ,X.CONTRACT_SEQ ,X.KEP_USER_ID ,X.KEP_PHONE_NUMBER ,X.IMAGE_KEY FROM( SELECT A.BUYER ,C.COM_NAME_LOC AS BUYER_NAME ,A.RAV_NO ,A.RAV_SEQ ,A.STATUS ,A.RFQ_USER_ID ,(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.RFQ_USER_ID) AS RFQ_USER_NAME ,A.BUYER_ITEM_NO ,A.ITEM_STATUS ,A.DESCRIPTION ,A.SPECIFICATION ,A.UNIT_MEASURE ,A.MAKER_NAME ,A.BUYER_REMARK ,B.RAV_SEQ AS KEP_RAV_SEQ ,B.BUYER_ITEM_NO AS KEP_BUYER_ITEM_NO ,B.ITEM_STATUS AS KEP_ITEM_STATUS ,B.DESCRIPTION AS KEP_DESCRIPTION ,B.SPECIFICATION AS KEP_SPECIFICATION ,B.MAKER_NAME AS KEP_MAKER_NAME ,B.UNIT_MEASURE AS KEP_UNIT_MEASURE ,B.KEP_REMARK AS KEP_KEP_REMARK ,A.FEEDBACK_FLAG AS FEEDBACK_FLAG ,NVL(B.CONTRACT_NO, '') AS CONTRACT_NO ,NVL(B.CONTRACT_SEQ, '') AS CONTRACT_SEQ ,(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = B.KEP_USER_ID) AS KEP_USER_ID ,(SELECT PHONE_NUMBER FROM ICOMLUSR WHERE USER_ID = B.KEP_USER_ID) AS KEP_PHONE_NUMBER ,A.IMAGE_KEY FROM TBL_RFQ_ATTRI_VERIFY A, TBL_RFQ_ATTRI_VERIFY B, ICOMCMPY C WHERE 1=1 AND A.BUYER = B.BUYER(+) AND A.RAV_NO = B.RAV_NO(+) AND A.BUYER = C.COM_CODE
AND A.BUYER =#{st_buyer_code}
AND A.RAV_NO LIKE #{st_ser_rav_no} || '%'
AND A.FEEDBACK_FLAG = #{st_fb_flag}
AND A.RFQ_USER_ID = #{st_btoa_user_id}
AND A.DESCRIPTION LIKE '%' || #{st_se_description} || '%'
AND A.RAV_SEQ = 1 AND B.RAV_SEQ(+) = 2 AND A.STATUS <> 'D' ORDER BY A.RAV_NO )X ) Y
ORDER BY $KEPORDERBY$

mapper.update:

UPDATE TBL_RFQ_ATTRI_VERIFY /*updateMasterMpRqItemReqRcpt*/
	SET STATUS = 'D'
		,KEP_REMARK = KEP_REMARK ||' DELETE(USER : '|| #{RFQ_USER_ID} ||', DATE : ' || TO_CHAR(SYSDATE,'YYYY/MM/DD HH24:MI:SS')|| ')'
WHERE BUYER = #{BUYER}
	AND RAV_NO = #{RAV_NO}
	AND RAV_SEQ = #{RAV_SEQ}

