ER_ID) AS KEP_PHONE_NUMBER ,A.IMAGE_KEY FROM TBL_RFQ_ATTRI_BOARD A, TBL_RFQ_ATTRI_BOARD B, ICOMCMPY C WHERE 1=1 AND A.BUYER = B.BUYER(+) AND A.RAV_NO = B.RAV_NO(+) AND A.BUYER = C.COM_CODE
