AND A.DESCRIPTION LIKE '%' || #{st_se_description} || '%'
AND A.RAV_SEQ = 1 AND B.RAV_SEQ(+) = 2 AND A.STATUS <> 'D' ORDER BY A.RAV_NO )X ) Y
ORDER BY $KEPORDERBY$

